def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    cc = dd = 0
    opp_d = 0
    for i in range(n):
        a, b = history[i]
        if b == 'D':
            opp_d += 1
        if i > 0:
            _, prev_b = history[i - 1]
            if prev_b == 'C' and b == 'C':
                cc += 1
            elif prev_b == 'D' and b == 'D':
                dd += 1

    opp_c = n - opp_d
    last_me, last_opp = history[-1]
    _, prev_opp = history[-2]

    remaining = 100 - n

    # Endgame: defect when it is safe.
    if remaining <= 2:
        return 'D'

    opp_rate = opp_d / float(n)

    # Persistent defector: cut losses.
    if opp_rate >= 0.75 and n >= 8:
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # Punish two consecutive defections, but forgive if they keep cooperating.
    if last_opp == 'D' and prev_opp == 'D':
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    # One defection: retaliate once, then return to cooperation.
    if last_opp == 'D':
        if last_me == 'D':
            return 'C'
        return 'D'

    # Opponent cooperated.
    if opp_rate > 0.55 and n >= 10:
        if rng.random() < 0.7:
            return 'D'
        return 'C'

    # Moderate defection rate: mostly cooperate, but occasionally probe.
    if opp_rate > 0.25:
        if rng.random() < 0.12:
            return 'D'
        return 'C'

    # Mostly cooperative opponent: occasional exploitation near end.
    if remaining <= 10:
        if rng.random() < 0.4:
            return 'D'
        return 'C'

    if n % 20 == 0 and rng.random() < 0.15:
        return 'D'

    return 'C'
